const fs = require('fs');
const http = require('http');
const statsJson = $input.first().json.stdout || '[]';
let umamiStats = [];
try { umamiStats = JSON.parse(statsJson); } catch (e) {}

const baseDir = '/data/automation-hub/projects/divinepilgrim/assets';
const playStoreUrl = 'https://play.google.com/store/apps/details?id=com.divinepilgrim.www.twa';

// Curated Scripture Promise & Reflection Bank (100% Free Local Fallback if Jetson Orin is ever offline)
const PROMISE_BANK = [
  '“The Lord will guide you always; He will satisfy your needs in a sun-scorched land and will strengthen your frame.” — Isaiah 58:11',
  '“Peace I leave with you; My peace I give you. Do not let your hearts be troubled and do not be afraid.” — John 14:27',
  '“Come to Me, all you who are weary and burdened, and I will give you rest.” — Matthew 11:28',
  '“The Lord is close to the brokenhearted and saves those who are crushed in spirit.” — Psalm 34:18',
  '“Trust in the Lord with all your heart and lean not on your own understanding; in all your ways submit to Him.” — Proverbs 3:5–6',
  '“Be strong and courageous. Do not be afraid; do not be discouraged, for the Lord your God will be with you wherever you go.” — Joshua 1:9',
  '“God is our refuge and strength, an ever-present help in trouble.” — Psalm 46:1',
  '“Those who hope in the Lord will renew their strength. They will soar on wings like eagles.” — Isaiah 40:31',
  '“The steadfast love of the Lord never ceases; His mercies never come to an end; they are new every morning.” — Lamentations 3:22–23',
  '“Cast all your anxiety on Him because He cares for you.” — 1 Peter 5:7',
  '“Your word is a lamp for my feet, a light on my path.” — Psalm 119:105',
  '“And surely I am with you always, to the very end of the age.” — Matthew 28:20',
  '“He heals the brokenhearted and binds up their wounds.” — Psalm 147:3',
  '“For I know the plans I have for you, declares the Lord, plans to prosper you and not to harm you, plans to give you hope and a future.” — Jeremiah 29:11'
];

// Persistent sequential counter so every day advances 0..143 without skipping or repeating early
const stateFile = '/data/automation-hub/projects/divinepilgrim/reel-sequence-state.json';
const todayKey = new Date().toISOString().slice(0, 10);
let state = { dayCounter: 0, lastDate: '' };
try {
  if (fs.existsSync(stateFile)) {
    state = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
  }
} catch (e) {}

if (state.lastDate && state.lastDate !== todayKey) {
  state.dayCounter = (state.dayCounter + 1) % 144;
}
state.lastDate = todayKey;
try {
  fs.writeFileSync(stateFile, JSON.stringify(state, null, 2));
} catch (e) {}

const now = new Date();
const dow = now.getDay(); // 0 (Sun) .. 6 (Sat)
const cycleIndex = state.dayCounter; // 0..143
const season = cycleIndex < 72 ? 1 : 2; // Season 1 (Days 1-72: Hook/Clue 1), Season 2 (Days 73-144: Story/Clue 2)

function splitTwoLines(text) {
  const words = (text || '').replace(/['"\n]/g, '').split(' ');
  let line1 = '';
  let line2 = '';
  for (const w of words) {
    if ((line1 + ' ' + w).trim().length <= 46) {
      line1 = (line1 + ' ' + w).trim();
    } else if ((line2 + ' ' + w).trim().length <= 46) {
      line2 = (line2 + ' ' + w).trim();
    } else {
      line2 = (line2 + '...').slice(0, 49);
      break;
    }
  }
  return [line1, line2];
}

// Primary: Query local Jetson Orin Nano (jetson-ai -> qwen3.5:4b, 100% free local GPU)
// Fallback: Built-In Scripture Promise Bank (0 cloud cost)
function askJetsonAi(promptText) {
  return new Promise((resolve) => {
    const payload = JSON.stringify({
      model: 'qwen3.5:4b',
      prompt: promptText,
      stream: false,
      options: { temperature: 0.7, num_predict: 75 }
    });
    const req = http.request({
      hostname: 'jetson-ai',
      port: 11434,
      path: '/api/generate',
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) },
      timeout: 4500
    }, (res) => {
      let body = '';
      res.on('data', (c) => body += c);
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body);
          const clean = (parsed.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
          resolve(clean ? { text: clean, source: 'Jetson Orin Nano (qwen3.5:4b)' } : null);
        } catch (e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.write(payload);
    req.end();
  });
}

// Tue (2) & Thu (4) = Sacred Architecture (30 Wonders x 2 Seasons = 60 Reels)
// Sun/Mon/Wed/Fri/Sat = Sacred Trails (42 Stops x 2 Seasons = 84 Reels)
const isArchitectureDay = (dow === 2 || dow === 4);

if (isArchitectureDay) {
  const archCatalog = JSON.parse(fs.readFileSync('/data/automation-hub/projects/divinepilgrim/sacred-architecture-30.json', 'utf8'));
  const archItem = archCatalog[cycleIndex % archCatalog.length] || archCatalog[0];
  const isSeason2 = (season === 2);
  const clueText = isSeason2
    ? ((archItem.fact3 || archItem.fact2) + '. ' + (archItem.significance || archItem.fact1))
    : (archItem.fact1 + '. ' + archItem.fact2);
  const [line1, line2] = splitTwoLines(clueText);
  const audioFile = isSeason2 ? `arch_${archItem.id}_story.mp3` : archItem.audioFile;
  const slug = `arch_${archItem.id}_s${season}_reel`;
  const webUrl = 'https://divinepilgrim.com/sacred-architecture';

  const aiResult = await askJetsonAi(
    `Write one warm, inspiring 1-sentence Christian reflection (max 24 words) on faith, beauty, and God's faithfulness inspired by a historic sanctuary built in ${archItem.built} in ${archItem.country}. No quotes.`
  );
  const reflectionText = aiResult ? aiResult.text : PROMISE_BANK[cycleIndex % PROMISE_BANK.length];
  const reflectionSource = aiResult ? aiResult.source : 'Built-In Scripture Promise Bank';

  const cmd = [
    '/data/automation-hub/shared-tools/generate-reel.sh',
    '"' + baseDir + '/images/architecture/' + archItem.imageFile + '"',
    '"' + baseDir + '/audio/architecture/' + audioFile + '"',
    '"' + baseDir + '/audio/gregorian_chant.mp3"',
    '"SACRED ARCHITECTURE  |  WONDER #' + archItem.id + (isSeason2 ? ' (PART II)' : '') + '"',
    '"' + archItem.country.toUpperCase() + ' MYSTERY"',
    '"Built: ' + archItem.built + '  |  ' + (archItem.style.split(',')[0] || '').trim() + '"',
    '"' + line1 + '"',
    '"' + line2 + '"',
    '"Web: https://DivinePilgrim.com"',
    '"' + slug + '"'
  ].join(' ');

  const socialCaption = [
    `Begun in ${archItem.built} in the ${archItem.style} style, this breathtaking sanctuary in ${archItem.country} is one of the greatest marvels of Sacred Architecture on Earth.`,
    '',
    isSeason2 ? '🏛️ DEEPER ARCHITECTURAL CLUES (PART II):' : '🏛️ ARCHITECTURAL CLUES:',
    '• ' + (isSeason2 ? (archItem.fact3 || archItem.fact2) : archItem.fact1),
    '• ' + (isSeason2 ? (archItem.significance || archItem.fact1) : archItem.fact2),
    '',
    '✨ TODAY\'S PROMISE & REFLECTION:',
    reflectionText,
    '',
    '💬 Do you recognize this masterpiece? Drop its name or city in the comments!',
    '',
    '🌍 Walk the interactive 3D Globe & explore 2,000 years of Christian heritage & 30 Sacred Architecture Wonders (100% Free, No Login):',
    '👉 Web: ' + webUrl,
    '📱 Android App (Google Play): ' + playStoreUrl,
    '',
    '#PromisesAndParables #SacredArchitecture #ArchitectureHistory #ChristianHeritage #BibleHistory #HistoryMystery #Shorts'
  ].join('\n');

  const pinnedComment = [
    `💡 Architectural Hint: Located in ${archItem.city}, ${archItem.country}` + (archItem.architects ? ` (Architects: ${archItem.architects})` : '') + '.',
    '🌍 Explore all 30 Sacred Architecture Wonders on the 3D Globe: ' + webUrl,
    '📱 Or get the free Divine Pilgrim Android App on Google Play: ' + playStoreUrl
  ].join('\n');

  return [{
    json: {
      contentType: 'SACRED_ARCHITECTURE',
      season,
      cycleDay: cycleIndex + 1,
      reflectionSource,
      reflectionText,
      title: archItem.displayName,
      reelSlug: slug,
      renderCommand: cmd,
      socialContext: {
        youtubeTitle: isSeason2
          ? `The Hidden Story Inside This ${archItem.built} Sanctuary in ${archItem.country} 🏛️✨ | #Shorts`
          : `Built in ${archItem.built}: Do You Recognize This Sacred Masterpiece? 🏛️🌍 | #Shorts`,
        youtubeAndInstagramCaption: socialCaption,
        firstPinnedComment: pinnedComment,
        webUrl,
        androidPlayStoreUrl: playStoreUrl
      },
      umamiAnalytics: umamiStats
    }
  }];
} else {
  const catalog = JSON.parse(fs.readFileSync('/data/automation-hub/projects/divinepilgrim/saints-42-stops.json', 'utf8'));
  const saintTrail = catalog.find(c => c.dayIndex === dow) || catalog[0];
  const stopIndex = Math.floor(cycleIndex / 7) % 6;
  const stop = saintTrail.stops[stopIndex] || saintTrail.stops[0];
  const isSeason2 = (season === 2);

  const clueSource = isSeason2 ? (stop.clue2Text || stop.clue1Text) : stop.clue1Text;
  const [line1, line2] = splitTwoLines(clueSource);
  const audioFile = isSeason2
    ? stop.audioFile.replace('_hook.mp3', '_story.mp3')
    : stop.audioFile;
  const slug = `${saintTrail.saintId}_stop${stop.stopNumber}_s${season}_reel`;
  const webUrl = 'https://divinepilgrim.com/sacred-trails';

  const aiResult = await askJetsonAi(
    `Write one warm, inspiring 1-sentence Christian reflection (max 24 words) on faith, courage, and God's promises inspired by ${saintTrail.saintName} and ${stop.title}. No quotes.`
  );
  const reflectionText = aiResult ? aiResult.text : PROMISE_BANK[cycleIndex % PROMISE_BANK.length];
  const reflectionSource = aiResult ? aiResult.source : 'Built-In Scripture Promise Bank';

  const cmd = [
    '/data/automation-hub/shared-tools/generate-reel.sh',
    '"' + baseDir + '/images/trails/' + stop.imageFile + '"',
    '"' + baseDir + '/audio/narration/' + audioFile + '"',
    '"' + baseDir + '/audio/gregorian_chant.mp3"',
    '"FOOTSTEPS OF FAITH  |  ' + saintTrail.dayName + (isSeason2 ? ' (PART II)' : '') + '"',
    '"' + saintTrail.saintName + '"',
    '"Stop #' + stop.stopNumber + ' of 6  |  ' + (stop.eraLabel.split('·')[0] || '').trim() + '"',
    '"' + line1 + '"',
    '"' + line2 + '"',
    '"Web: https://DivinePilgrim.com"',
    '"' + slug + '"'
  ].join(' ');

  const socialCaption = [
    stop.leadPrompt,
    '',
    isSeason2
      ? '🔍 TODAY\'S DEEPER CLUE #2 (' + stop.clue2Headline + '):'
      : '🔍 TODAY\'S CLUE #1 (' + stop.clue1Headline + '):',
    '"' + clueSource + '"',
    '',
    '✨ TODAY\'S PROMISE & REFLECTION:',
    reflectionText,
    '',
    '💬 Do you know which city this is? Drop your guess in the comments!',
    '',
    '🌍 Walk the interactive 3D Globe & explore 2,000 years of Christian heritage (100% Free, No Login):',
    '👉 Web: ' + webUrl,
    '📱 Android App (Google Play): ' + playStoreUrl,
    '',
    '#PromisesAndParables #FootstepsOfFaith #BibleHistory #ChristianEncouragement #ChristianHeritage #' + saintTrail.shortTitle.replace(/[^a-zA-Z]/g, '') + ' #Shorts'
  ].join('\n');

  const pinnedComment = [
    '💡 Extra Historical Clue: ' + (isSeason2 ? stop.clue1Text : stop.clue2Text),
    '🌍 Walk the interactive 3D Globe & explore all 7 Sacred Trails: ' + webUrl,
    '📱 Or get the free Divine Pilgrim Android App on Google Play: ' + playStoreUrl
  ].join('\n');

  return [{
    json: {
      contentType: 'SACRED_TRAILS',
      season,
      cycleDay: cycleIndex + 1,
      reflectionSource,
      reflectionText,
      dayOfWeek: saintTrail.dayName,
      saint: saintTrail.saintName,
      stopNumber: stop.stopNumber,
      stopTitle: stop.title,
      reelSlug: slug,
      renderCommand: cmd,
      socialContext: {
        youtubeTitle: isSeason2
          ? `${stop.title}: The Deeper Story 🌍 | Footsteps of Faith (${saintTrail.shortTitle}) #Shorts`
          : `${stop.title} 🌍 | Footsteps of Faith (${saintTrail.shortTitle}) #Shorts`,
        youtubeAndInstagramCaption: socialCaption,
        firstPinnedComment: pinnedComment,
        webUrl,
        androidPlayStoreUrl: playStoreUrl
      },
      umamiAnalytics: umamiStats
    }
  }];
}

const fs = require('fs');
const prev = $('2. Build 144-Reel Context (Season 1 & 2 + Jetson AI)').first().json;
let renderResult = {};
try {
  renderResult = JSON.parse($input.first().json.stdout || '{}');
} catch (e) {
  renderResult = { raw: $input.first().json.stdout };
}

const metaPayloadPath = '/tmp/current-meta-payload.json';
try {
  fs.writeFileSync(metaPayloadPath, JSON.stringify({
    videoUrlHttps: renderResult.public_https_url,
    title: prev.socialContext.youtubeTitle,
    caption: prev.socialContext.youtubeAndInstagramCaption
  }, null, 2));
} catch (e) {}

return [{
  json: {
    status: 'READY_TO_PUBLISH',
    contentType: prev.contentType,
    season: prev.season,
    cycleDayOf144: prev.cycleDay,
    reflectionSource: prev.reflectionSource,
    reflectionText: prev.reflectionText,
    videoUrlHttps: renderResult.public_https_url,
    videoLocalFile: renderResult.file,
    videoDurationSec: renderResult.duration_sec,
    youtubeTitle: prev.socialContext.youtubeTitle,
    captionForYouTubeInstagramTikTok: prev.socialContext.youtubeAndInstagramCaption,
    pinnedCommentClue2: prev.socialContext.firstPinnedComment,
    webUrl: prev.socialContext.webUrl,
    androidPlayStoreUrl: prev.socialContext.androidPlayStoreUrl,
    umamiTrafficSummary: prev.umamiAnalytics,
    metaPayloadPath
  }
}];

const fs = require('fs');
const path = require('path');
const item = $input.first();
const filePath = item.json.videoLocalFile;
const buffer = fs.readFileSync(filePath);
const fileName = path.basename(filePath);
const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, 'video/mp4');
binaryData.mimeType = 'video/mp4';
binaryData.fileExtension = 'mp4';
binaryData.fileName = fileName;

return [{
  json: item.json,
  binary: {
    data: binaryData
  }
}];
